from fractions import Fraction

def R(n):
    if n < 4:
        return Fraction(0)
    f = n * (n - 1) * (n - 2) // 6
    g = n * (n - 1) * (n - 2) * (n - 3) // 24
    return (g**3) / (f**4)

def check_refuted(c_val):
    for n in range(4, 500):
        if R(n) > c_val:
            return True, n, R(n)
    return False, None, None

c_c = Fraction(1, 28)
refuted_c, n_c, val_c = check_refuted(c_c)
print(f"Candidate C (1/28) refuted by K_{n_c} with R = {val_c}")

c_d = Fraction(1, 16)
