import itertools

def count_triangles(edges, n):
    triangles = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (i, j) in edges and (j, k) in edges and (i, k) in edges:
                    triangles += 1
    return triangles

def count_tetrahedra(edges, n):
    tetrahedra = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if (i, j) in edges and (j, k) in edges and (i, k) in edges and \
                       (j, l) in edges and (k, l) in edges and (i, l) in edges:
                        tetrahedra += 1
    return tetrahedra

max_ratio = 0
for n in range(4, 15):
    # Test complete graph K_n
    edges = set()
    for i in range(n):
        for j in range(i + 1, n):
            edges.add((i, j))
    f = count_triangles(edges, n)
    g = count_tetrahedra(edges, n)
    if f > 0:
        ratio = (g**3) / (f**4)
        print(f"K_{n}: f={f}, g={g}, ratio={ratio}")
        if ratio > max_ratio:
            max_ratio = ratio

print(f"Max ratio found: {max_ratio}")
